<?php $titulo='Cuentas por pagar';include __DIR__.'/_inicio.php'; ?>
<p>Confirma el abono después de realizarlo. Cada pago reduce la obligación y registra el egreso en la caja abierta.</p>
<div class="ops-table-wrap"><table class="ops-table"><caption>Hasta 200 obligaciones, ordenadas por vencimiento</caption><thead><tr><th>Referencia</th><th>Beneficiario</th><th>Vence</th><th>Original</th><th>Abonado</th><th>Saldo</th><th>Acción</th></tr></thead><tbody>
<?php foreach($filas as $o):$saldo=(int)$o['monto_centavos']-(int)$o['ajuste_centavos']-(int)$o['pagado_centavos']; ?><tr><td><?= s($o['referencia']) ?><small><?= s($o['origen']) ?></small></td><td><?= s($o['beneficiario']) ?></td><td><?= s($o['vence_en']) ?></td><td><?= s($dinero($o['monto_centavos'])) ?></td><td><?= s($dinero($o['pagado_centavos'])) ?></td><td><?= s($dinero(max(0,$saldo))) ?></td><td><?php if($saldo>0): ?><details><summary>Registrar abono</summary><?php $formulario=['accion'=>'obligacion_pagar','ocultos'=>['obligacion_id'=>$o['id']],'campos'=>['monto'=>['tipo'=>'number','etiqueta'=>'Abono USD','min'=>'0.01','paso'=>'0.01','max'=>\Services\CobroCalculo::plano($saldo)],'metodo'=>['tipo'=>'select','etiqueta'=>'Medio del abono realizado','opciones'=>['efectivo'=>'Efectivo','transferencia'=>'Transferencia verificada']],'referencia'=>['etiqueta'=>'Referencia del comprobante de pago','longitud'=>120]],'boton'=>'Confirmar abono realizado'];include __DIR__.'/_formulario.php'; ?></details><?php endif; ?>
<?php if($o['origen']==='compra'): ?><details><summary>Registrar nota de crédito</summary><?php $formulario=['accion'=>'proveedor_credito','ocultos'=>['obligacion_id'=>$o['id']],'campos'=>['monto'=>['etiqueta'=>'Importe de la nota USD','tipo'=>'number','min'=>'0.01','paso'=>'0.01'],'referencia'=>['etiqueta'=>'Documento del proveedor','longitud'=>120],'motivo'=>['etiqueta'=>'Motivo de la nota','longitud'=>300]]];include __DIR__.'/_formulario.php'; ?></details>
<?php $recuperable=max(0,-$saldo-(int)$o['recuperado']);if($recuperable>0): ?><details><summary>Recuperar <?= s($dinero($recuperable)) ?> del proveedor</summary><p>Confirma únicamente el reintegro recibido.</p><?php $formulario=['accion'=>'proveedor_recuperar','ocultos'=>['obligacion_id'=>$o['id']],'campos'=>['monto'=>['etiqueta'=>'Importe recibido USD','tipo'=>'number','min'=>'0.01','max'=>\Services\CobroCalculo::plano($recuperable),'paso'=>'0.01'],'metodo'=>['etiqueta'=>'Medio verificado','tipo'=>'select','opciones'=>['efectivo'=>'Efectivo','transferencia'=>'Transferencia verificada']],'referencia'=>['etiqueta'=>'Referencia del reintegro','longitud'=>120]]];include __DIR__.'/_formulario.php'; ?></details><?php endif; ?>
<?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div>
